import{_}from"./xNwnxVR1.js";import{_ as n,n as c,c as l,a as i,b as d,a3 as m,o as v}from"./BCG_L7Kq.js";const o={class:"payment-page"},g={class:"payment-page__container"},e="Оплата — Indigo",t="Способы оплаты, сроки зачисления, подтверждение оплаты и реквизиты продавца.",y={__name:"payment",setup(r){const p=[{label:"Главная",to:"/"},{label:"Правовая информация",to:"/legal-information"},{label:"Оплата",to:""}];return c({title:e,description:t,ogTitle:e,ogDescription:t}),(x,a)=>{const s=_;return v(),l("main",o,[i("div",g,[d(s,{items:p,class:"payment-page__breadcrumbs"}),a[0]||(a[0]=m('<article class="payment-page__card" data-v-5216058e><h1 class="payment-page__title" data-v-5216058e> Оплата </h1><div class="payment-page__content" data-v-5216058e><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Способы оплаты </h2><div class="payment-page__subsection" data-v-5216058e><h3 class="payment-page__h3" data-v-5216058e> Система быстрых платежей (СБП) </h3><p class="payment-page__text" data-v-5216058e> Отсканируйте QR-код в приложении вашего банка. Деньги поступают мгновенно, комиссия для покупателя — 0 ₽. Платежи обрабатываются через ВТБ. </p><p class="payment-page__text" data-v-5216058e> Как это работает: вы оформляете заказ → нажимаете «Оплатить по СБП» → на экране появляется QR-код → открываете приложение банка → сканируете код → подтверждаете оплату → заказ переходит в статус «оплачен». </p><p class="payment-page__text" data-v-5216058e> QR-код действует ограниченное время. Если не успели оплатить — оформите заказ заново или свяжитесь с нами для повторного QR-кода. </p></div><div class="payment-page__subsection" data-v-5216058e><h3 class="payment-page__h3" data-v-5216058e> Безналичный расчёт для юридических лиц и ИП </h3><p class="payment-page__text" data-v-5216058e> Оформите заказ через корзину и выберите «Безналичный расчёт». Укажите наименование организации, ИНН и контактный email. </p><p class="payment-page__text" data-v-5216058e> Как это работает: вы оформляете заказ → мы формируем счёт с уникальным номером заказа → отправляем его через систему ЭДО (Диадок / Контур) и дублируем на email → ваш бухгалтер формирует платёжное поручение → деньги поступают на наш расчётный счёт → заказ переходит в работу. </p><p class="payment-page__text" data-v-5216058e> Счёт поступит в течение 2 рабочих дней после оформления заказа. Срок оплаты — 2 рабочих дня. До поступления средств заказ находится в статусе «ожидает оплаты». Если оплата не поступила в срок, мы свяжемся с вами для уточнения. </p><p class="payment-page__text" data-v-5216058e> В назначении платежа обязательно укажите номер заказа — он будет в счёте. Это нужно для автоматической сверки платежа с заказом. Пример: «Оплата по счёту № ИНД-000123 от 01.01.2026». </p></div></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Валюта и цены </h2><p class="payment-page__text" data-v-5216058e> Все цены на сайте указаны в российских рублях и включают НДС 5. Цена, зафиксированная в момент оформления заказа, не меняется — даже если товар подорожал после оформления. </p></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Когда списываются деньги </h2><p class="payment-page__text" data-v-5216058e> СБП — деньги списываются сразу после подтверждения в приложении банка. Заказ переходит в статус «оплачен» и передаётся в сборку. </p><p class="payment-page__text" data-v-5216058e> Безналичный расчёт — деньги поступают на расчётный счёт в течение 1–3 рабочих дней после формирования платёжного поручения. До поступления средств заказ находится в статусе «ожидает оплаты». После сверки банковской выписки с номером заказа вы получите подтверждение на email. </p><p class="payment-page__text" data-v-5216058e> Если товара нет в наличии или заказ невозможно выполнить, мы вернём деньги тем же способом, которым вы оплатили. Срок возврата — до 10 рабочих дней. </p></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Подтверждение оплаты </h2><p class="payment-page__text" data-v-5216058e> СБП — электронный кассовый чек формируется после оплаты и отправляется на email, указанный при заказе. Чек создаётся автоматически через онлайн-кассу в соответствии с 54-ФЗ и передаётся в ФНС. </p><p class="payment-page__text" data-v-5216058e> Безналичный расчёт — после поступления средств на расчётный счёт и сверки с заказом мы отправим подтверждение оплаты на email. Закрывающие документы (УПД / накладная/акт) предоставляются через ЭДО. </p><p class="payment-page__text payment-page__text_indent" data-v-5216058e> • Если подтверждение не пришло — напишите нам: info@indigo-mail.ru </p></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Безопасность платежей </h2><p class="payment-page__text" data-v-5216058e> СБП — платежи обрабатываются через ВТБ. Оплата проходит в приложении вашего банка — мы не получаем и не храним данные ваших счетов или карт. </p><p class="payment-page__text" data-v-5216058e> Безналичный расчёт — счета и закрывающие документы передаются через защищённый канал ЭДО с электронной подписью или при получении. </p><p class="payment-page__text" data-v-5216058e> Сайт работает по протоколу HTTPS — все данные передаются в зашифрованном виде. </p><p class="payment-page__text" data-v-5216058e> При подозрении на несанкционированное списание — свяжитесь с вашим банком и с нами: info@indigo-mail.ru, +7 949-499-69-79. </p></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Проблемы с оплатой </h2><div class="payment-page__subsection" data-v-5216058e><h3 class="payment-page__h3" data-v-5216058e> СБП </h3><p class="payment-page__text" data-v-5216058e> Если платёж не прошёл, проверьте: </p><ul class="payment-page__list" data-v-5216058e><li class="payment-page__text" data-v-5216058e> достаточно ли средств на счёте; </li><li class="payment-page__text" data-v-5216058e> поддерживает ли ваш банк оплату по QR-коду через СБП; </li><li class="payment-page__text" data-v-5216058e> обновлено ли приложение банка до последней версии; </li><li class="payment-page__text" data-v-5216058e> не истёк ли срок действия QR-кода. </li></ul></div><div class="payment-page__subsection" data-v-5216058e><h3 class="payment-page__h3" data-v-5216058e> Безналичный расчёт </h3><p class="payment-page__text" data-v-5216058e> Если заказ остаётся в статусе «ожидает оплаты», проверьте: </p><ul class="payment-page__list" data-v-5216058e><li class="payment-page__text" data-v-5216058e> верно ли указаны реквизиты в платёжном поручении; </li><li class="payment-page__text" data-v-5216058e> указан ли номер заказа в назначении платежа; </li><li class="payment-page__text" data-v-5216058e> не истёк ли срок оплаты по счёту. </li></ul></div><p class="payment-page__text" data-v-5216058e> Если деньги отправлены, но статус заказа не изменился в течение 3 рабочих дней — пришлите копию платёжного поручения на info@indigo-mail.ru и мы проведём сверку вручную. </p><p class="payment-page__text" data-v-5216058e> По любым вопросам: +7 949-499-69-79, info@indigo-mail.ru </p></section><section class="payment-page__section" data-v-5216058e><h2 class="payment-page__h2" data-v-5216058e> Реквизиты продавца </h2><div class="payment-page__requisites" data-v-5216058e><p class="payment-page__text payment-page__text_strong" data-v-5216058e> ИНДИВИДУАЛЬНЫЙ ПРЕДПРИНИМАТЕЛЬ <br data-v-5216058e> РУЧКО АНАСТАСИЯ ВИКТОРОВНА </p><p class="payment-page__text" data-v-5216058e> ИНН 930900107014, ОГРНИП 323930100105541 <br data-v-5216058e> Юр. Адрес: ДНР, 283054, г. Донецк, Донецкий округ, ул. Аристова, д.1, <br data-v-5216058e> р/с 40802810100810222405 в российских рублях, ФИЛИАЛ &quot;ЦЕНТРАЛЬНЫЙ&quot; <br data-v-5216058e> БАНКА ВТБ, (ПАО), г Москва. БИК 044525411 <br data-v-5216058e> 30101810145250000411 <br data-v-5216058e> Тел.: +7 949-131-45-44 <br data-v-5216058e> E-mail: info@indigo-mail.ru </p><p class="payment-page__text" data-v-5216058e> ИП </p><p class="payment-page__text" data-v-5216058e> ____________________ А.В. Ручко </p></div></section></div></article>',1))])])}}},b=n(y,[["__scopeId","data-v-5216058e"]]);export{b as default};
